//! Responses generated by the proxy itself.

use chosproxy_core::brand;

/// A complete synthesized HTTP/1.1 response.
pub(crate) fn plain(status: u16, reason: &str, body: &str, close: bool) -> Vec<u8> {
    format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: text/plain; charset=utf-8\r\n\
         Content-Length: {}\r\nCache-Control: no-store\r\nConnection: {}\r\n\r\n{body}",
        body.len(),
        if close { "close" } else { "keep-alive" }
    )
    .into_bytes()
}

/// An error response whose body names the product so users can tell proxy
/// errors from upstream errors.
pub(crate) fn error(status: u16, reason: &str, detail: &str, close: bool) -> Vec<u8> {
    let body = format!("{}: {detail}\n", brand().product_name);
    plain(status, reason, &body, close)
}

/// `407` asking the client for proxy credentials. The connection is closed:
/// a request body may follow and is not read.
pub(crate) fn proxy_auth_required() -> Vec<u8> {
    let body = format!(
        "{}: this proxy listener requires a user name and password\n",
        brand().product_name
    );
    format!(
        "HTTP/1.1 407 Proxy Authentication Required\r\n\
         Proxy-Authenticate: Basic realm=\"{}\", charset=\"UTF-8\"\r\n\
         Content-Type: text/plain; charset=utf-8\r\nContent-Length: {}\r\n\
         Cache-Control: no-store\r\nConnection: close\r\n\r\n{body}",
        brand().product_name,
        body.len()
    )
    .into_bytes()
}

/// Page served when a browser requests the proxy itself
/// (`http://chosproxy/` or the listener address).
pub(crate) fn info_page(ca_available: bool, close: bool) -> Vec<u8> {
    let name = &brand().product_name;
    let ca = if ca_available {
        "<h2>CA certificate</h2>\
         <p>To inspect HTTPS, this browser must trust your local CA certificate. \
         It was generated on your machine; its private key never leaves it.</p>\
         <p><a href=\"/cert\">Download CA certificate (.crt, DER)</a> · \
         <a href=\"/cert.pem\">PEM</a></p>\
         <p>Firefox: Settings → Privacy &amp; Security → Certificates → View Certificates → \
         Authorities → Import, then tick “Trust this CA to identify websites”. \
         Only do this in a browser profile dedicated to testing.</p>"
    } else {
        "<p>HTTPS interception is unavailable: the local CA is not loaded. \
         Check Proxy → HTTPS in the application.</p>"
    };
    let body = format!(
        "<!doctype html><html><head><meta charset=\"utf-8\"><title>{name}</title></head>\
         <body style=\"font-family:sans-serif;max-width:42em;margin:3em auto;line-height:1.5\">\
         <h1>{name} is running</h1>\
         <p>This browser is talking to the {name} proxy listener; the traffic you browse \
         is captured in the project history.</p>{ca}\
         <p>Only use {name} against systems you own or are authorized to test.</p>\
         </body></html>"
    );
    format!(
        "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\n\
         Cache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n\
         Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'\r\n\
         Connection: {}\r\n\r\n{body}",
        body.len(),
        if close { "close" } else { "keep-alive" }
    )
    .into_bytes()
}

/// The CA certificate as a download (DER `.crt` or PEM).
pub(crate) fn certificate(body: &[u8], pem: bool, close: bool) -> Vec<u8> {
    let (ctype, file) = if pem {
        ("application/x-pem-file", "chosproxy-ca.pem")
    } else {
        ("application/x-x509-ca-cert", "chosproxy-ca.crt")
    };
    let mut out = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: {ctype}\r\nContent-Length: {}\r\n\
         Content-Disposition: attachment; filename=\"{file}\"\r\nCache-Control: no-store\r\n\
         X-Content-Type-Options: nosniff\r\nConnection: {}\r\n\r\n",
        body.len(),
        if close { "close" } else { "keep-alive" }
    )
    .into_bytes();
    out.extend_from_slice(body);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn content_length_matches_body() {
        for raw in [
            plain(502, "Bad Gateway", "x\u{e9}", true),
            info_page(true, false),
            info_page(false, true),
        ] {
            let text = String::from_utf8(raw).unwrap();
            let (head, body) = text.split_once("\r\n\r\n").unwrap();
            let cl: usize = head
                .lines()
                .find_map(|l| l.strip_prefix("Content-Length: "))
                .unwrap()
                .parse()
                .unwrap();
            assert_eq!(cl, body.len());
        }
    }
}
